  didClickOption(option) {
    return setTimeout(this.commitSuggestion, 100)
  }

  didShowResults(element) {
    this.hidden = false
    return this.delegate.didShowResults?.(element)
  }

  didHideResults(element) {
    this.hidden = true
    return this.delegate.didHideResults?.(element)
  }

