    if (this.#active) {
      if (this.hidden) {
        this.#displayResults()
        return false
      } else if (!this.#committing) {
        if (this.commitSuggestion()) {
          return false
        }
      }
    } else if (this.#canceled) {
      this.#resumeSuggestion()
      return false
    }
  }

  #didPressReturnKey() {
    if (this.#active) {
      if (this.commitSuggestion()) {
        return false
      }
    }
  }

  #didPressEscapeKey() {
    if (this.#active) {
      this.#cancelSuggestion()
      return false
    }
  }

  #didPressSpaceKey() {
    if (this.#active && this.#spaceMatchesWordBoundary()) {
