        return false
      }
    }
  }

  #didPressUpKey() {
    if (this.#active) {
      this.#resultsController.selectUp()
      return false
    }
  }

  #didPressDownKey() {
    if (this.#active) {
      this.#resultsController.selectDown()
      return false
    }
  }

  #didPressKeyWithValue(value) {
    if (this.#active && (value != null) && !this.hidden) {
      const result = this.matchQueryAndTerminatorForWord(value)
      if (result?.query === "") {
